jQuery(window).on("elementor/frontend/init",function(){elementorFrontend.hooks.addAction("frontend/element_ready/google-review-widget.default",function($scope){const slider=$scope.find(".review-cards");if(!slider.length)return;let slidesToShow=parseInt(slider.attr("data-review-count"),10)||1;if(slider.hasClass("slick-initialized")){slider.slick("unslick")}slider.on("init",function(){removeButtonButtons();applyRandomColors(".initial",["#ab47bc","#00897b","#8d6e63","#ea4335","#689f38"])});slider.slick({infinite:true,draggable:false,dots:true,arrows:false,autoplaySpeed:2e3,slidesToShow:1,adaptiveHeight:true,prevArrow:`<button class="slick-arrow --prev"></button>`,nextArrow:`<button class="slick-arrow --next"></button>`,mobileFirst:true,responsive:[{breakpoint:1024,settings:{slidesToShow:slidesToShow,dots:false,arrows:true}},{breakpoint:900,settings:{slidesToShow:2,dots:false,arrows:true}},{breakpoint:576,settings:{slidesToShow:2}}]});$scope.on("click",".extend-button",function(){toggleReviewHeight(this,true)});$scope.on("click",".reduce-button",function(){toggleReviewHeight(this,false)});function applyRandomColors(selector,colors){jQuery(selector).each(function(){jQuery(this).css("background-color",colors[Math.floor(Math.random()*colors.length)])})}function toggleReviewHeight(button,expand){const DEFAULT_HEIGHT="130px";const ANIMATION_DURATION=300;const parentCard=jQuery(button).closest(".review-card");const reviewTextElement=parentCard.find(".review-text");if(!reviewTextElement.length)return;const newHeight=expand?`${reviewTextElement[0].scrollHeight+10}px`:DEFAULT_HEIGHT;reviewTextElement.animate({height:newHeight},ANIMATION_DURATION);parentCard.find(".extend-button").toggleClass("--hidden",expand);parentCard.find(".reduce-button").toggleClass("--hidden",!expand)}function removeButtonButtons(){jQuery(".review-card").each(function(){const textContainer=jQuery(this).find(".review-text");const extendButton=jQuery(this).find(".extend-button");const reduceButton=jQuery(this).find(".reduce-button");if(!textContainer.length||!extendButton.length||!reduceButton.length)return;if(textContainer[0].clientHeight>=textContainer[0].scrollHeight){extendButton.remove();reduceButton.remove()}})}})});